              "{\"inLanguage\":\"en\",\"headline\":\"Donald Trump delays tariff; says US, China trade deal is in 'phase one' | Mint\",\"datePublished\":\"2019-10-12T12:19:33+05:30\",\"dateModified\":\"2019-10-12T12:19:34+05:30\",\"alternativeHeadline\":\"Donald Trump delays tariff; says US, China trade deal is in 'phase one' | Mint\",\"author\":{\"name\":\"Bloomberg\"},\"publisher\":{\"name\":\"mint\"},\"keywords\":[\"donald trump\",\"xi jinping\",\"donald trump xi jinping\",\"us china trade war\",\"us china trade talks\",\"us tariff on chinese goods\",\"us china deal\",\"us china trade deal\",\"xi jinping donald trump\"]}"
